diff --git a/src/rate-limit.js b/src/rate-limit.js
new file mode 100644
--- /dev/null
+++ b/src/rate-limit.js
@@
+const WINDOW_MS = 60_000
+const MAX_HITS = 5
+const buckets = new Map() // ip -> { count, windowStart }
+
+function allow(ip) {
+  const now = Date.now()
+  let b = buckets.get(ip)
+  if (!b) {
+    b = { count: 0, windowStart: now }
+    buckets.set(ip, b)
+  }
+  if (now - b.windowStart > WINDOW_MS) {
+    b.count = 0
+    b.windowStart = now
+  }
+  b.count += 1
+  return b.count <= MAX_HITS
+}
+
+module.exports = { allow }

diff --git a/src/login.js b/src/login.js
--- a/src/login.js
+++ b/src/login.js
@@
 const { verifyPassword } = require('./auth')
+const { allow } = require('./rate-limit')

 async function login(req, res) {
+  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress
+  if (!allow(ip)) {
+    return res.status(429).send('Too many attempts')
+  }
   const { user, password } = req.body
   const ok = await verifyPassword(user, password)
   if (ok) return res.status(200).send('ok')
   return res.status(401).send('bad credentials')
 }

 module.exports = { login }
